import os
import base64
from typing import Optional

import boto3
from botocore.config import Config
from botocore.exceptions import ClientError


class EnvelopeEncryptionError(Exception):
    pass


class KmsEnvelopeEncryption:
    def __init__(self, kms_key_id: str, region_name: Optional[str] = None):
        self.kms_key_id = kms_key_id
        self.region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"

        self.kms = boto3.client(
            "kms",
            region_name=self.region_name,
            config=Config(retries={"max_attempts": 10, "mode": "standard"}),
        )

    def encrypt(self, plaintext: bytes, encryption_context: Optional[dict] = None) -> dict:
        try:
            data_key_resp = self.kms.generate_data_key(
                KeyId=self.kms_key_id,
                KeySpec="AES_256",
                EncryptionContext=encryption_context or {},
            )
            plaintext_data_key = data_key_resp["Plaintext"]
            encrypted_data_key = data_key_resp["CiphertextBlob"]

            try:
                from cryptography.hazmat.primitives.ciphers.aead import AESGCM
            except ImportError as e:
                raise EnvelopeEncryptionError("cryptography package is required") from e

            iv = os.urandom(12)
            aesgcm = AESGCM(plaintext_data_key)
            ciphertext = aesgcm.encrypt(iv, plaintext, None)

            return {
                "provider": "aws-kms",
                "region": self.region_name,
                "kms_key_id": self.kms_key_id,
                "algorithm": "AES-256-GCM",
                "encrypted_data_key": base64.b64encode(encrypted_data_key).decode("utf-8"),
                "iv": base64.b64encode(iv).decode("utf-8"),
                "ciphertext": base64.b64encode(ciphertext).decode("utf-8"),
                "encryption_context": encryption_context or {},
            }
        except ClientError as e:
            raise EnvelopeEncryptionError(f"AWS KMS encrypt failed: {e}") from e

    def decrypt(self, envelope: dict) -> bytes:
        try:
            encrypted_data_key = base64.b64decode(envelope["encrypted_data_key"])
            iv = base64.b64decode(envelope["iv"])
            ciphertext = base64.b64decode(envelope["ciphertext"])
            encryption_context = envelope.get("encryption_context") or {}

            decrypt_resp = self.kms.decrypt(
                CiphertextBlob=encrypted_data_key,
                EncryptionContext=encryption_context,
            )
            plaintext_data_key = decrypt_resp["Plaintext"]

            try:
                from cryptography.hazmat.primitives.ciphers.aead import AESGCM
            except ImportError as e:
                raise EnvelopeEncryptionError("cryptography package is required") from e

            aesgcm = AESGCM(plaintext_data_key)
            return aesgcm.decrypt(iv, ciphertext, None)
        except ClientError as e:
            raise EnvelopeEncryptionError(f"AWS KMS decrypt failed: {e}") from e
        except KeyError as e:
            raise EnvelopeEncryptionError(f"Invalid envelope format, missing field: {e}") from e
        except Exception as e:
            if isinstance(e, EnvelopeEncryptionError):
                raise
            raise EnvelopeEncryptionError(f"Envelope decrypt failed: {e}") from e
